async function metricValue(db2, g7) {
  const range2 = { gte: startOfDayIST(g7.startDate), lt: addDays(startOfDayIST(g7.endDate), 1) };
  const co2 = g7.companyId ? { companyId: g7.companyId } : {};
  switch (g7.metricType) {
    case "REVENUE":
      return Number((await db2.payment.aggregate({ _sum: { amount: true }, where: { date: range2, invoice: co2 } }))._sum.amount ?? 0);
    case "NEW_CLIENTS":
      return db2.client.count({ where: { createdAt: range2, ...g7.companyId && { companies: { some: { companyId: g7.companyId } } } } });
    case "PROJECTS_COMPLETED":
      return db2.project.count({ where: { ...co2, status: "COMPLETED", completedAt: range2 } });
    case "VIDEOS_DELIVERED":
      return db2.task.count({ where: { companyId: "vmh", productionStage: "DELIVERED", deliveredAt: range2 } });
    case "LEADS_WON":
      return db2.lead.count({ where: { ...co2, stage: "WON", wonAt: range2 } });
    case "BILLABLE_HOURS":
      return Number((await db2.timeEntry.aggregate({ _sum: { durationMin: true }, where: { ...co2, billable: true, status: "APPROVED", start: range2 } }))._sum.durationMin ?? 0) / 60;
    default:
      return null;
  }
}
async function recomputeGoals(db2, now3, where = {}) {
  const companies = await db2.company.findMany({ select: { id: true, settings: true } });
  const thresholds = Object.fromEntries(companies.map((c6) => [c6.id, parseCompanySettings(c6.settings).goalThresholds]));
  const goals2 = await db2.goal.findMany({ where: { ...where, endDate: { gte: new Date(now3.getTime() - 7 * 864e5) } } });
  let changed = 0;
  for (const g7 of goals2) {
    const auto = await metricValue(db2, g7);
    const current = auto ?? Number(g7.currentValue);
    const status = goalStatus({ progress: goalProgress({ ...g7, currentValue: current }), startDate: g7.startDate, endDate: g7.endDate, now: now3, thresholds: thresholds[g7.companyId ?? "vmh"] });
    if (status !== g7.status || current !== Number(g7.currentValue)) {
      await db2.goal.update({ where: { id: g7.id }, data: { status, currentValue: current } });
      changed++;
    }
  }
  return changed;
}

