function projectProgress(input2) {
  const { template, deliverables, milestones } = input2;
  if (template === "VMH") {
    const target = deliverables.reduce((a7, d6) => a7 + (d6.targetCount ?? 0), 0);
    if (target > 0) return Math.round(deliverables.reduce((a7, d6) => a7 + Math.min(d6.completedCount ?? 0, d6.targetCount ?? 0), 0) / target * 100);
  } else if (deliverables.length) {
    return Math.round(deliverables.reduce((a7, d6) => a7 + (d6.percent ?? 0), 0) / deliverables.length);
  }
  if (milestones.length) return Math.round(milestones.filter((m6) => m6.status === "COMPLETED").length / milestones.length * 100);
  return 0;
}

